import sys
import json


def solve(req):
    ebits = req["ebits"]
    fbits = req["fbits"]
    mode = req["mode"]
    pairs = req["pairs"]

    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Fmask = F - 1
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    sshift = ebits + fbits  # position of the sign bit

    any_nan = False
    invalid = False
    pos_inf = False
    neg_inf = False

    prods = []            # nonzero finite products: (sign, mant, exp2)
    n_products = 0        # count of all finite products (incl. zeros)
    all_neg_zero = True   # whether every product so far is a negative zero

    for pair in pairs:
        va = int(pair[0], 16)
        vb = int(pair[1], 16)
        has_nan = False
        info = []
        for v in (va, vb):
            s = (v >> sshift) & 1
            e = (v >> fbits) & Eall
            f = v & Fmask
            if e == Eall:
                if f == 0:
                    info.append((s, "inf", 0, 0))
                else:
                    quiet = (f >> (fbits - 1)) & 1
                    info.append((s, "qnan" if quiet else "snan", 0, 0))
                    has_nan = True
                    any_nan = True
                    if not quiet:
                        invalid = True
            elif e == 0:
                if f == 0:
                    info.append((s, "zero", 0, 0))
                else:
                    info.append((s, "fin", f, 1 - bias - fbits))
            else:
                info.append((s, "fin", F + f, e - bias - fbits))
        if has_nan:
            # A NaN pair contributes no product, no infinite product,
            # and cannot count as zero times infinity.
            continue
        (sa, ka, ma, xa), (sb, kb, mb, xb) = info
        if ka == "inf" or kb == "inf":
            if ka == "zero" or kb == "zero":
                invalid = True
            elif sa ^ sb:
                neg_inf = True
            else:
                pos_inf = True
            continue
        n_products += 1
        sp = sa ^ sb
        if ka == "zero" or kb == "zero":
            if sp == 0:
                all_neg_zero = False
            continue
        all_neg_zero = False
        prods.append((sp, ma * mb, xa + xb))

    if pos_inf and neg_inf:
        invalid = True

    if any_nan or invalid:
        bits = (Eall << fbits) | (1 << (fbits - 1))  # canonical NaN
        return {"bits": format(bits, "x"),
                "flags": ["invalid"] if invalid else []}

    if pos_inf or neg_inf:
        bits = ((1 if neg_inf else 0) << sshift) | (Eall << fbits)
        return {"bits": format(bits, "x"), "flags": []}

    # Exact sum of finite products, all as integers scaled by 2**e0.
    if prods:
        e0 = min(p[2] for p in prods)
        total = 0
        for sp, m, x in prods:
            t = m << (x - e0)
            total = total - t if sp else total + t
    else:
        total = 0
        e0 = 0

    if total == 0:
        neg = (mode == "RDN") or (n_products > 0 and all_neg_zero)
        bits = (1 << sshift) if neg else 0
        return {"bits": format(bits, "x"), "flags": []}

    if total < 0:
        sign = 1
        A = -total
    else:
        sign = 0
        A = total

    # x = A * 2**e0 is the exact magnitude.
    L = A.bit_length() - 1 + e0            # floor(log2(x))
    q = emin - fbits
    if L - fbits > q:
        q = L - fbits                       # quantum exponent
    shift = q - e0
    if shift <= 0:
        n = A << (-shift)
        rem = 0
    else:
        n = A >> shift
        rem = A & ((1 << shift) - 1)

    if rem:
        if mode == "RUP":
            up = sign == 0
        elif mode == "RDN":
            up = sign == 1
        elif mode == "RNE":
            half = 1 << (shift - 1)
            up = rem > half or (rem == half and (n & 1))
        elif mode == "RNA":
            up = rem >= (1 << (shift - 1))
        else:  # RTZ
            up = False
        if up:
            n += 1
    inexact = rem != 0
    # Rounded magnitude is y = n * 2**q.

    t = emax + 1 - q
    overflow = (n >= 1) if t <= 0 else (n >= (1 << t))
    if overflow:
        if mode == "RNE" or mode == "RNA":
            to_inf = True
        elif mode == "RUP":
            to_inf = sign == 0
        elif mode == "RDN":
            to_inf = sign == 1
        else:  # RTZ
            to_inf = False
        if to_inf:
            bits = (sign << sshift) | (Eall << fbits)
        else:
            bits = (sign << sshift) | ((Eall - 1) << fbits) | Fmask
        return {"bits": format(bits, "x"), "flags": ["overflow", "inexact"]}

    flags = []
    if inexact:
        if n == 0:
            tiny = True
        elif q < emin:
            tiny = n < (1 << (emin - q))
        else:
            tiny = False
        if tiny:
            flags.append("underflow")
        flags.append("inexact")

    if n == 0:
        bits = sign << sshift              # nonzero exact value rounded to zero
    else:
        Lp = n.bit_length() - 1 + q        # floor(log2(y))
        if Lp >= emin:                     # normal
            e_field = Lp + bias
            sh2 = n.bit_length() - 1 - fbits
            m = (n >> sh2) if sh2 >= 0 else (n << (-sh2))
            bits = (sign << sshift) | (e_field << fbits) | (m - F)
        else:                              # subnormal
            f_field = n << (q - (emin - fbits))
            bits = (sign << sshift) | f_field
    return {"bits": format(bits, "x"), "flags": flags}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))) + "\n")


if __name__ == "__main__":
    main()
