"""Independent reference implementation using exact Fraction arithmetic.

Written separately from main.py (different structure) for cross-checking.
"""
from fractions import Fraction


def pow2(e):
    return Fraction(1 << e, 1) if e >= 0 else Fraction(1, 1 << (-e))


def floor_log2(v):
    # v is a positive Fraction; returns floor(log2(v)).
    k = v.numerator.bit_length() - v.denominator.bit_length()
    if v < pow2(k):
        return k - 1
    if v >= pow2(k + 1):
        return k + 1
    return k


def decode(v, ebits, fbits):
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    s = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & Eall
    f = v & (F - 1)
    if e == Eall:
        if f == 0:
            return (s, "inf", None)
        return (s, "qnan" if (f >> (fbits - 1)) & 1 else "snan", None)
    if e == 0:
        if f == 0:
            return (s, "zero", Fraction(0))
        return (s, "fin", Fraction(f) * pow2(1 - bias - fbits))
    return (s, "fin", Fraction(F + f) * pow2(e - bias - fbits))


def ref_solve(req):
    ebits = req["ebits"]; fbits = req["fbits"]; mode = req["mode"]
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    sshift = ebits + fbits

    any_nan = invalid = pos_inf = neg_inf = False
    total = Fraction(0)
    n_products = 0
    all_neg_zero = True

    for ha, hb in req["pairs"]:
        da = decode(int(ha, 16), ebits, fbits)
        db = decode(int(hb, 16), ebits, fbits)
        kinds = {da[1], db[1]}
        if "qnan" in kinds or "snan" in kinds:
            any_nan = True
            if "snan" in kinds:
                invalid = True
            continue
        if "inf" in kinds:
            if "zero" in kinds:
                invalid = True
            elif da[0] ^ db[0]:
                neg_inf = True
            else:
                pos_inf = True
            continue
        n_products += 1
        sp = da[0] ^ db[0]
        val = da[2] * db[2]
        if val == 0:
            if sp == 0:
                all_neg_zero = False
        else:
            all_neg_zero = False
            total += -val if sp else val

    if pos_inf and neg_inf:
        invalid = True
    if any_nan or invalid:
        bits = (Eall << fbits) | (1 << (fbits - 1))
        return {"bits": format(bits, "x"), "flags": ["invalid"] if invalid else []}
    if pos_inf or neg_inf:
        bits = ((1 if neg_inf else 0) << sshift) | (Eall << fbits)
        return {"bits": format(bits, "x"), "flags": []}

    if total == 0:
        neg = (mode == "RDN") or (n_products > 0 and all_neg_zero)
        return {"bits": format((1 << sshift) if neg else 0, "x"), "flags": []}

    sign = 1 if total < 0 else 0
    x = -total if total < 0 else total
    L = floor_log2(x)
    qe = max(emin - fbits, L - fbits)
    r = x / pow2(qe)          # positive Fraction
    n, rem = divmod(r.numerator, r.denominator)
    if rem:
        if mode == "RUP":
            up = sign == 0
        elif mode == "RDN":
            up = sign == 1
        elif mode == "RNE":
            twice = rem * 2
            up = twice > r.denominator or (twice == r.denominator and n % 2 == 1)
        elif mode == "RNA":
            up = rem * 2 >= r.denominator
        else:
            up = False
        if up:
            n += 1
    y = Fraction(n) * pow2(qe)

    if y >= pow2(emax + 1):
        if mode in ("RNE", "RNA"):
            to_inf = True
        elif mode == "RUP":
            to_inf = sign == 0
        elif mode == "RDN":
            to_inf = sign == 1
        else:
            to_inf = False
        if to_inf:
            bits = (sign << sshift) | (Eall << fbits)
        else:
            bits = (sign << sshift) | ((Eall - 1) << fbits) | (F - 1)
        return {"bits": format(bits, "x"), "flags": ["overflow", "inexact"]}

    flags = []
    if y != x:
        if y < pow2(emin):
            flags.append("underflow")
        flags.append("inexact")

    if n == 0:
        bits = sign << sshift
    else:
        Lp = floor_log2(y)
        if Lp >= emin:
            e_field = Lp + bias
            m = y / pow2(Lp - fbits)
            assert m.denominator == 1
            f_field = int(m) - F
            assert 0 <= f_field < F and 1 <= e_field <= Eall - 1
            bits = (sign << sshift) | (e_field << fbits) | f_field
        else:
            m = y / pow2(emin - fbits)
            assert m.denominator == 1
            f_field = int(m)
            assert 0 < f_field < F
            bits = (sign << sshift) | f_field
    return {"bits": format(bits, "x"), "flags": flags}
